export function checkSummary(out: string, expect: Expect) {
  const fails: string[] = [];
  const bullets = out.split("\n").filter((l) => l.startsWith("- "));
  if (bullets.length > 3) fails.push("too many bullets");
  if (expect.exact && out.trim() !== expect.exact) {
    fails.push("expected the exact fallback text");
  }
  for (const w of expect.include ?? []) {
    if (!out.toLowerCase().includes(w)) fails.push(`missing ${w}`);
  }
  return fails;
}

const cases = await loadJsonl("evals/summary.jsonl");
let passed = 0;
for (const c of cases) {
  const out = await summarize(c.note); // the real app code
  const fails = [
    ...checkSummary(out, c.expect),
    ...(await judge(c.note, out)),
  ];
  if (fails.length === 0) passed++;
  else console.log(`FAIL ${c.id}: ${fails.join(", ")}`);
}
console.log(`score ${passed} / ${cases.length}`);
if (passed < BASELINE) process.exit(1);
